export const CAPSTONES = {"1-0":{"en":"Set up and organise a digital life","hi":"अपना डिजिटल जीवन सेट करें और व्यवस्थित करें","brief":{"en":"Create an email account, organise files into named folders on your phone, and write a one-page safety checklist for your family.","hi":"एक ईमेल खाता बनाएं, अपने फ़ोन में फ़ाइलों को नाम वाले फ़ोल्डरों में रखें, और अपने परिवार के लिए एक पेज की सुरक्षा चेकलिस्ट लिखें।"},"criteria":["An email account exists and you can send and receive a message with an attachment","At least three folders with clear names hold your photos, documents and downloads","A written safety checklist covers passwords, OTPs, and one common scam","You can explain, in your own words, what a browser, a file and an account are"]},"1-1":{"en":"Help someone else get online","hi":"किसी और को ऑनलाइन लाने में मदद करें","brief":{"en":"Guide a family member or friend through creating an account, setting a strong password, and completing one online form or government service.","hi":"किसी परिवार के सदस्य या दोस्त को खाता बनाने, मज़बूत पासवर्ड रखने और एक ऑनलाइन फ़ॉर्म या सरकारी सेवा पूरी करने में मार्गदर्शन दें।"},"criteria":["The other person completed the task themselves with your guidance","You wrote down the steps as a short guide someone else could follow","The password used is unique and not written in plain sight","You identified one thing that confused them and how you explained it"]},"1-2":{"en":"Run a digital basics workshop","hi":"डिजिटल बेसिक्स वर्कशॉप चलाएं","brief":{"en":"Plan and deliver a 45-minute session for at least three learners on one digital topic, with a printed handout.","hi":"कम से कम तीन सीखने वालों के लिए एक डिजिटल विषय पर 45 मिनट का सत्र योजना बनाकर चलाएं, एक प्रिंटेड हैंडआउट के साथ।"},"criteria":["A written plan lists the goal, steps and timing","A one-page handout exists in Hindi or English","Learners completed one hands-on task during the session","You collected one line of feedback from each learner"]},"1-3":{"en":"Design a community digital-literacy curriculum","hi":"सामुदायिक डिजिटल साक्षरता पाठ्यक्रम डिज़ाइन करें","brief":{"en":"Write a four-session curriculum for a library or community centre, with objectives, activities and an assessment for each session.","hi":"लाइब्रेरी या सामुदायिक केंद्र के लिए चार सत्रों का पाठ्यक्रम लिखें, हर सत्र के उद्देश्य, गतिविधियां और मूल्यांकन के साथ।"},"criteria":["Four sessions each have objectives, activities, materials and an assessment","The curriculum is reviewed by one mentor or centre coordinator","One session has been piloted and the notes are attached","Materials are free to reuse and cite their sources"]},"2-0":{"en":"Typed, formatted, calculated","hi":"टाइप किया, फ़ॉर्मेट किया, गणना की","brief":{"en":"Reach 25 words per minute, write a one-page formatted letter, and build a monthly expense sheet with totals.","hi":"25 शब्द प्रति मिनट तक पहुंचें, एक पेज का फ़ॉर्मेट किया पत्र लिखें, और कुल योग वाली मासिक खर्च शीट बनाएं।"},"criteria":["A typing test screenshot shows 25 wpm or more with 90% accuracy","The letter uses a heading, paragraphs, bold text and a saved PDF copy","The expense sheet uses SUM and has at least 15 rows and a total","Files are saved with clear names in a folder you can find again"]},"2-1":{"en":"A small-office toolkit","hi":"छोटे ऑफ़िस की टूलकिट","brief":{"en":"Produce a presentation, a mail-merge letter set, and a spreadsheet with a chart and a lookup formula for a real or imagined small business.","hi":"किसी असली या काल्पनिक छोटे व्यवसाय के लिए एक प्रेज़ेंटेशन, मेल-मर्ज पत्र सेट, और चार्ट व लुकअप फ़ॉर्मूला वाली स्प्रेडशीट बनाएं।"},"criteria":["Presentation has at least 6 slides with consistent design","Mail merge produces at least 5 personalised letters from a list","Spreadsheet uses VLOOKUP or XLOOKUP and one chart","A mentor can open every file without errors"]},"2-2":{"en":"An automated monthly report","hi":"एक स्वचालित मासिक रिपोर्ट","brief":{"en":"Build a spreadsheet report with pivot tables, conditional formatting and data validation that updates when new rows are added.","hi":"पिवट टेबल, कंडीशनल फ़ॉर्मेटिंग और डेटा वैलिडेशन वाली स्प्रेडशीट रिपोर्ट बनाएं जो नई पंक्तियां जुड़ने पर अपडेट हो।"},"criteria":["Adding 10 new rows updates the pivot and chart without manual edits","Data validation prevents at least two kinds of wrong input","A one-page written guide explains how to use the report","Formulas are documented in a notes sheet"]},"2-3":{"en":"Office automation with scripts","hi":"स्क्रिप्ट से ऑफ़िस ऑटोमेशन","brief":{"en":"Automate a repetitive office task using Apps Script, VBA or Python and document the before/after time saved.","hi":"Apps Script, VBA या Python से एक दोहराया जाने वाला ऑफ़िस काम स्वचालित करें और पहले/बाद में बचे समय को दर्ज करें।"},"criteria":["The script runs end to end on a fresh copy of the data","A README explains setup and the task it replaces","Time saved is measured and recorded","Errors in input are handled with a clear message"]},"3-0":{"en":"Your first working program","hi":"आपका पहला चलता हुआ प्रोग्राम","brief":{"en":"Write a small program (Scratch or Python) that asks the user questions and responds differently based on the answers, using loops and conditions.","hi":"एक छोटा प्रोग्राम (Scratch या Python) लिखें जो उपयोगकर्ता से सवाल पूछे और जवाबों के आधार पर अलग प्रतिक्रिया दे, लूप और कंडीशन का उपयोग करते हुए।"},"criteria":["The program runs without errors from start to finish","It uses at least one loop and one if/else decision","It handles a wrong input without crashing","You can explain each line in your own words"]},"3-1":{"en":"A command-line tool people can use","hi":"एक कमांड-लाइन टूल जिसे लोग उपयोग कर सकें","brief":{"en":"Build a text-based app (to-do list, quiz, or expense tracker) that saves data to a file and loads it again next time.","hi":"एक टेक्स्ट-आधारित ऐप (टू-डू लिस्ट, क्विज़ या खर्च ट्रैकर) बनाएं जो डेटा फ़ाइल में सहेजे और अगली बार फिर लोड करे।"},"criteria":["Data persists between runs using a file","Code is split into at least three functions","Invalid input produces a helpful message, not a crash","The code is in a Git repository with at least five commits"]},"3-2":{"en":"A program that talks to the outside world","hi":"बाहरी दुनिया से बात करने वाला प्रोग्राम","brief":{"en":"Build a project that reads data from a public API or file, processes it with your own data structures, and produces a report or visual output, with tests.","hi":"एक प्रोजेक्ट बनाएं जो सार्वजनिक API या फ़ाइल से डेटा पढ़े, अपने डेटा स्ट्रक्चर से प्रोसेस करे, और रिपोर्ट या विज़ुअल आउटपुट दे, टेस्ट के साथ।"},"criteria":["At least five automated tests pass","Code uses classes or modules sensibly","Errors from the network or file are handled","A README explains how to run it in under five steps"]},"3-3":{"en":"Teach the language back","hi":"भाषा को वापस सिखाएं","brief":{"en":"Write a short open-source library or teaching series that explains one advanced language feature with runnable examples and benchmarks.","hi":"एक छोटी ओपन-सोर्स लाइब्रेरी या शिक्षण श्रृंखला लिखें जो एक उन्नत भाषा फ़ीचर को चलने वाले उदाहरणों और बेंचमार्क के साथ समझाए।"},"criteria":["Published publicly with a licence","Examples run and are covered by tests","Includes a benchmark or measured comparison","Received and addressed at least one piece of outside feedback"]},"4-0":{"en":"A personal web page, online","hi":"एक निजी वेब पेज, ऑनलाइन","brief":{"en":"Build a one-page site about yourself or a local business with HTML and CSS, make it look right on a phone, and publish it for free.","hi":"HTML और CSS से अपने या किसी स्थानीय व्यवसाय के बारे में एक पेज की साइट बनाएं, फ़ोन पर सही दिखाएं, और मुफ़्त प्रकाशित करें।"},"criteria":["The page is live at a public URL (GitHub Pages, Netlify or similar)","Layout works at phone width without horizontal scrolling","Uses headings, an image, a list and a link correctly","HTML passes the W3C validator with no errors"]},"4-1":{"en":"An interactive web app","hi":"एक इंटरैक्टिव वेब ऐप","brief":{"en":"Build a multi-page or single-page app (e.g. a shop menu, quiz, or notes app) with JavaScript that stores data in the browser and fetches from at least one API.","hi":"JavaScript से एक बहु-पेज या सिंगल-पेज ऐप (जैसे दुकान मेनू, क्विज़ या नोट्स ऐप) बनाएं जो ब्राउज़र में डेटा रखे और कम से कम एक API से डेटा लाए।"},"criteria":["Data survives a page reload using localStorage","At least one fetch from a public API with loading and error states","Code is in Git with meaningful commit messages","Works on a phone and a desktop browser"]},"4-2":{"en":"A full-stack app with users","hi":"उपयोगकर्ताओं वाला फुल-स्टैक ऐप","brief":{"en":"Build and deploy an app with a backend, a database, user login, and automated tests. Write a short document on its architecture.","hi":"बैकएंड, डेटाबेस, यूज़र लॉगिन और स्वचालित टेस्ट वाला ऐप बनाकर डिप्लॉय करें। इसकी आर्किटेक्चर पर एक छोटा दस्तावेज़ लिखें।"},"criteria":["Deployed backend and frontend are reachable publicly","Login works and passwords are never stored in plain text","At least ten automated tests pass in CI","Architecture doc explains data flow with a diagram"]},"4-3":{"en":"Production-grade delivery","hi":"प्रोडक्शन-स्तर की डिलीवरी","brief":{"en":"Take an existing app to production quality: performance budget, accessibility audit, monitoring, and a written incident runbook.","hi":"किसी मौजूदा ऐप को प्रोडक्शन गुणवत्ता तक ले जाएं: परफ़ॉर्मेंस बजट, एक्सेसिबिलिटी ऑडिट, मॉनिटरिंग और लिखित इंसिडेंट रनबुक।"},"criteria":["Lighthouse performance and accessibility scores above 90 on mobile","Monitoring alerts on errors or downtime","Runbook covers three failure scenarios","A code review from another developer is addressed"]},"5-0":{"en":"Ask questions of real data","hi":"असली डेटा से सवाल पूछें","brief":{"en":"Take a public dataset (for example from data.gov.in), clean it in a spreadsheet, and answer five questions using formulas, filters and one chart.","hi":"एक सार्वजनिक डेटासेट लें (जैसे data.gov.in से), उसे स्प्रेडशीट में साफ़ करें, और फ़ॉर्मूला, फ़िल्टर और एक चार्ट से पांच सवालों के जवाब दें।"},"criteria":["Source and download date of the data are recorded","At least three cleaning steps are listed","Five questions each have an answer and the formula used","One chart has a title and labelled axes"]},"5-1":{"en":"A small relational database","hi":"एक छोटा रिलेशनल डेटाबेस","brief":{"en":"Design and populate a database with at least three related tables (e.g. a library or shop) and write ten SQL queries including joins and aggregates.","hi":"कम से कम तीन जुड़ी हुई तालिकाओं वाला डेटाबेस डिज़ाइन कर भरें (जैसे लाइब्रेरी या दुकान) और जॉइन व एग्रीगेट सहित दस SQL क्वेरी लिखें।"},"criteria":["An ER diagram shows tables, keys and relationships","Ten queries run correctly, including at least two joins and two GROUP BY","Data has no duplicate primary keys","Queries are saved in a .sql file with comments"]},"5-2":{"en":"A data pipeline with a dashboard","hi":"डैशबोर्ड वाली डेटा पाइपलाइन","brief":{"en":"Build a scripted pipeline that loads raw data into a database, transforms it, and feeds a dashboard that answers a business question.","hi":"एक स्क्रिप्टेड पाइपलाइन बनाएं जो कच्चा डेटा डेटाबेस में लोड करे, बदले, और एक डैशबोर्ड को खिलाए जो व्यवसायिक सवाल का जवाब दे।"},"criteria":["Pipeline reruns from scratch with one command","Transformations are tested on sample rows","Dashboard has at least three views tied to the question","Indexes or query plans are used to justify performance choices"]},"5-3":{"en":"Database internals or optimisation study","hi":"डेटाबेस इंटरनल्स या ऑप्टिमाइज़ेशन अध्ययन","brief":{"en":"Implement a storage or query component (e.g. a B-tree, a join algorithm) or tune a large workload and write up measured results.","hi":"एक स्टोरेज या क्वेरी घटक लागू करें (जैसे B-tree, जॉइन एल्गोरिदम) या एक बड़े वर्कलोड को ट्यून करें और मापे गए परिणाम लिखें।"},"criteria":["Correctness verified by tests against a reference","Benchmarks with methodology and numbers are documented","Write-up explains trade-offs","Reviewed by a mentor or peer"]},"6-0":{"en":"A one-page data story","hi":"एक पेज की डेटा कहानी","brief":{"en":"Choose a local topic (weather, prices, exam results), collect or download data, compute averages and ranges, and present three charts with a plain-language conclusion.","hi":"एक स्थानीय विषय चुनें (मौसम, दाम, परीक्षा परिणाम), डेटा जुटाएं या डाउनलोड करें, औसत और रेंज निकालें, और सरल भाषा के निष्कर्ष के साथ तीन चार्ट दिखाएं।"},"criteria":["Data source and size are stated","Mean, median and range are computed correctly","Three charts each answer one question","Conclusion avoids claims the data cannot support"]},"6-1":{"en":"An exploratory analysis notebook","hi":"एक खोजपूर्ण विश्लेषण नोटबुक","brief":{"en":"Using Python (pandas) or R, clean a real dataset, explore it with plots, test one hypothesis, and publish the notebook.","hi":"Python (pandas) या R से एक असली डेटासेट साफ़ करें, प्लॉट से खोजें, एक परिकल्पना परखें, और नोटबुक प्रकाशित करें।"},"criteria":["Notebook runs top to bottom without errors","Missing values and outliers are handled and explained","A statistical test is used and interpreted correctly","Published on Kaggle or GitHub with a summary"]},"6-2":{"en":"A predictive model, honestly evaluated","hi":"एक पूर्वानुमान मॉडल, ईमानदारी से मूल्यांकित","brief":{"en":"Build a model on a real problem with train/validation/test split, compare against a baseline, and report limitations.","hi":"एक असली समस्या पर train/validation/test विभाजन के साथ मॉडल बनाएं, बेसलाइन से तुलना करें, और सीमाएं बताएं।"},"criteria":["Baseline and model metrics are reported on held-out data","Feature engineering is documented","Limitations and possible biases are stated","Code is reproducible with fixed random seeds"]},"6-3":{"en":"A research-grade study","hi":"एक शोध-स्तर का अध्ययन","brief":{"en":"Design and run a study with a pre-registered question, appropriate statistical method, and a write-up that could be reviewed.","hi":"एक पूर्व-पंजीकृत प्रश्न, उपयुक्त सांख्यिकीय विधि और समीक्षा योग्य लेख के साथ अध्ययन डिज़ाइन कर चलाएं।"},"criteria":["Question and method were written before seeing results","Assumptions of the method are checked","Effect sizes and uncertainty are reported","Peer or mentor review is attached"]},"7-0":{"en":"Use AI tools well and safely","hi":"AI टूल का अच्छा और सुरक्षित उपयोग","brief":{"en":"Complete five real tasks with an AI assistant (writing, summarising, planning), record the prompts, and note where the AI was wrong.","hi":"AI सहायक से पांच असली काम पूरे करें (लिखना, सारांश, योजना), प्रॉम्प्ट दर्ज करें, और नोट करें AI कहां गलत था।"},"criteria":["Five prompts and outputs are saved","At least two mistakes by the AI are identified and corrected","A short note explains what data should never be pasted into AI tools","You can explain in your own words what an LLM does and does not know"]},"7-1":{"en":"A first machine-learning model","hi":"पहला मशीन-लर्निंग मॉडल","brief":{"en":"Train a classification or regression model on a public dataset, evaluate it properly, and build a tiny app or notebook others can try.","hi":"सार्वजनिक डेटासेट पर एक वर्गीकरण या रिग्रेशन मॉडल प्रशिक्षित करें, ठीक से मूल्यांकन करें, और एक छोटा ऐप या नोटबुक बनाएं जिसे दूसरे आज़मा सकें।"},"criteria":["Accuracy or error is reported on a test set, not training data","Overfitting is checked and discussed","Others can run it from a notebook or simple interface","Data licence and source are cited"]},"7-2":{"en":"An LLM-powered application","hi":"LLM-संचालित एप्लिकेशन","brief":{"en":"Build an app that uses an LLM API with retrieval over your own documents, includes evaluation of answers, and handles failures.","hi":"अपने दस्तावेज़ों पर रिट्रीवल के साथ LLM API का उपयोग करने वाला ऐप बनाएं, जवाबों का मूल्यांकन शामिल हो, और विफलताओं को संभाले।"},"criteria":["Retrieval improves answers on a written test set of 20 questions","Prompt injection and unsafe outputs are considered","Costs and latency are measured","Code and evaluation are in a repository"]},"7-3":{"en":"Reproduce and extend a paper","hi":"एक पेपर को पुनरुत्पादित और विस्तारित करें","brief":{"en":"Reimplement a published model or result, reproduce the key numbers, and add one original experiment.","hi":"एक प्रकाशित मॉडल या परिणाम को फिर से लागू करें, मुख्य संख्याएं पुनरुत्पादित करें, और एक मौलिक प्रयोग जोड़ें।"},"criteria":["Reproduced numbers are within a stated tolerance of the paper","Deviations are explained","The original experiment has a hypothesis and result","Write-up is shared publicly"]},"8-0":{"en":"Algorithms by hand and by code","hi":"हाथ से और कोड से एल्गोरिदम","brief":{"en":"Implement three classic algorithms (search, sort, and one on a list or stack), trace them by hand on paper, and time them on growing inputs.","hi":"तीन क्लासिक एल्गोरिदम लागू करें (सर्च, सॉर्ट, और एक लिस्ट या स्टैक पर), उन्हें कागज़ पर ट्रेस करें, और बढ़ते इनपुट पर समय मापें।"},"criteria":["Hand traces are photographed or scanned","Code passes given test cases","A table shows running time for at least four input sizes","You can state the time complexity of each"]},"8-1":{"en":"Fifty solved problems with notes","hi":"नोट्स के साथ पचास हल की गई समस्याएं","brief":{"en":"Solve 50 problems across arrays, strings, hashing, trees and graphs; for ten of them write a short approach note.","hi":"ऐरे, स्ट्रिंग, हैशिंग, ट्री और ग्राफ़ पर 50 समस्याएं हल करें; उनमें से दस के लिए छोटा अप्रोच नोट लिखें।"},"criteria":["50 accepted solutions across at least five topics","Ten approach notes explain the idea and complexity","At least five problems were solved without hints","A mentor reviews two solutions for clarity"]},"8-2":{"en":"A systems project","hi":"एक सिस्टम्स प्रोजेक्ट","brief":{"en":"Build a small shell, HTTP server, or key-value store from scratch with tests, and document the design decisions.","hi":"शून्य से एक छोटा शेल, HTTP सर्वर या key-value स्टोर बनाएं, टेस्ट के साथ, और डिज़ाइन निर्णयों का दस्तावेज़ बनाएं।"},"criteria":["Handles concurrent clients or processes correctly","Tests cover normal and error paths","Design doc explains trade-offs","Measured throughput or latency is reported"]},"8-3":{"en":"Advanced theory into practice","hi":"उन्नत सिद्धांत को व्यवहार में","brief":{"en":"Implement a distributed consensus, compression, or cryptographic primitive from a specification and verify it against known vectors.","hi":"एक विनिर्देश से डिस्ट्रिब्यूटेड सहमति, कम्प्रेशन या क्रिप्टोग्राफ़िक प्रिमिटिव लागू करें और ज्ञात वेक्टर से सत्यापित करें।"},"criteria":["Passes official or published test vectors","Failure modes are tested","Proof sketch or correctness argument is written","Reviewed by a mentor"]},"9-0":{"en":"Your first repository, from the terminal","hi":"टर्मिनल से आपकी पहली रिपॉज़िटरी","brief":{"en":"Using the command line, create a folder structure, write a README, initialise Git, make five commits, and push to GitHub.","hi":"कमांड लाइन से एक फ़ोल्डर संरचना बनाएं, README लिखें, Git शुरू करें, पांच कमिट करें, और GitHub पर पुश करें।"},"criteria":["Repository is public on GitHub with a README","Five commits have descriptive messages","You can list, move and delete files from the terminal","You can explain what a commit and a branch are"]},"9-1":{"en":"A Linux server you set up","hi":"आपके द्वारा सेट किया गया Linux सर्वर","brief":{"en":"Set up a Linux machine or VM, secure SSH access, install a web server, deploy a static site, and write a shell script that backs it up.","hi":"एक Linux मशीन या VM सेट करें, SSH सुरक्षित करें, वेब सर्वर स्थापित करें, स्थैतिक साइट डिप्लॉय करें, और बैकअप करने वाली शेल स्क्रिप्ट लिखें।"},"criteria":["Site is reachable over HTTP","Password SSH login is disabled in favour of keys","Backup script runs on a schedule (cron)","Steps are documented so a peer can repeat them"]},"9-2":{"en":"Containerised app with CI/CD","hi":"CI/CD के साथ कंटेनराइज़्ड ऐप","brief":{"en":"Containerise an application, write a CI pipeline that tests and builds it, and deploy automatically to a cloud service.","hi":"एक एप्लिकेशन को कंटेनराइज़ करें, एक CI पाइपलाइन लिखें जो टेस्ट और बिल्ड करे, और क्लाउड सेवा पर स्वतः डिप्लॉय करें।"},"criteria":["Dockerfile builds reproducibly","CI runs tests on every push and blocks failures","Deployment happens without manual steps","Secrets are not committed to the repository"]},"9-3":{"en":"Reliability engineering","hi":"रिलायबिलिटी इंजीनियरिंग","brief":{"en":"Define SLOs for a service, add monitoring and alerting, run a chaos or load test, and write a post-mortem for a simulated incident.","hi":"एक सेवा के लिए SLO तय करें, मॉनिटरिंग और अलर्टिंग जोड़ें, chaos या लोड टेस्ट चलाएं, और एक सिम्युलेटेड घटना का पोस्ट-मॉर्टम लिखें।"},"criteria":["SLOs and error budget are written down","Alerts fire on injected failure","Load test results are graphed","Post-mortem is blameless and lists actions"]},"10-0":{"en":"Secure yourself and your family","hi":"खुद को और परिवार को सुरक्षित करें","brief":{"en":"Audit five accounts for strong unique passwords and two-factor auth, recognise three phishing examples, and write a one-page home security guide.","hi":"पांच खातों में मज़बूत अनोखे पासवर्ड और टू-फ़ैक्टर ऑथ का ऑडिट करें, तीन फ़िशिंग उदाहरण पहचानें, और घर की सुरक्षा पर एक पेज की गाइड लिखें।"},"criteria":["Two-factor authentication is enabled on at least three accounts","Three phishing signs are explained with examples","Guide is written in plain Hindi or English","You can explain what a password manager does"]},"10-1":{"en":"Beginner CTF and a network map","hi":"शुरुआती CTF और नेटवर्क नक्शा","brief":{"en":"Complete 15 beginner challenges (e.g. Bandit or picoCTF), map your home or lab network, and write an approach note for five challenges.","hi":"15 शुरुआती चुनौतियां पूरी करें (जैसे Bandit या picoCTF), अपने घर या लैब के नेटवर्क का नक्शा बनाएं, और पांच चुनौतियों के लिए अप्रोच नोट लिखें।"},"criteria":["15 challenges completed with screenshots or flags","Network map lists devices, IPs and open services","Five approach notes explain tools and reasoning","Only systems you own or are authorised to test were used"]},"10-2":{"en":"A web security assessment","hi":"एक वेब सुरक्षा आकलन","brief":{"en":"Assess a deliberately vulnerable app (Juice Shop or WebGoat), find and document ten vulnerabilities with fixes, in a professional report.","hi":"एक जानबूझकर कमज़ोर ऐप (Juice Shop या WebGoat) का आकलन करें, दस कमज़ोरियां ढूंढकर सुधार के साथ पेशेवर रिपोर्ट में दर्ज करें।"},"criteria":["Ten findings each have severity, reproduction steps and a fix","Findings map to OWASP Top 10 categories","Report has an executive summary","Ethical scope statement is included"]},"10-3":{"en":"Original security research","hi":"मौलिक सुरक्षा शोध","brief":{"en":"Perform a deep analysis of a system (binary, protocol or codebase), produce a proof-of-concept for a weakness, and disclose responsibly.","hi":"एक सिस्टम (बाइनरी, प्रोटोकॉल या कोडबेस) का गहन विश्लेषण करें, कमज़ोरी का proof-of-concept बनाएं, और ज़िम्मेदारी से प्रकट करें।"},"criteria":["Analysis methodology is documented","PoC is reproducible in an isolated lab","Disclosure followed the vendor's or a coordinated policy","Mentor review of ethics and scope is attached"]},"11-0":{"en":"A first app on your own phone","hi":"आपके अपने फ़ोन पर पहला ऐप","brief":{"en":"Build a two-screen app (e.g. a tip calculator or unit converter) with Flutter or Kotlin, run it on a real phone, and record a short demo.","hi":"Flutter या Kotlin से दो-स्क्रीन ऐप बनाएं (जैसे टिप कैलकुलेटर या यूनिट कन्वर्टर), असली फ़ोन पर चलाएं, और छोटा डेमो रिकॉर्ड करें।"},"criteria":["App installs and runs on a physical device","Two screens with navigation between them","Handles empty or wrong input gracefully","Demo video under two minutes"]},"11-1":{"en":"An app that remembers and fetches","hi":"याद रखने और डेटा लाने वाला ऐप","brief":{"en":"Build an app with a list, local storage, and data from a public API, with loading and error states.","hi":"एक ऐप बनाएं जिसमें सूची, लोकल स्टोरेज और सार्वजनिक API से डेटा हो, लोडिंग और एरर स्थितियों के साथ।"},"criteria":["Data persists after the app is closed","API failures show a friendly message","List scrolls smoothly with 100+ items","Code in Git with a README and screenshots"]},"11-2":{"en":"A published app with a backend","hi":"बैकएंड वाला प्रकाशित ऐप","brief":{"en":"Ship an app with authentication, cloud data (e.g. Firebase), tests, and an internal or open testing release.","hi":"प्रमाणीकरण, क्लाउड डेटा (जैसे Firebase), टेस्ट और आंतरिक या ओपन टेस्टिंग रिलीज़ के साथ ऐप शिप करें।"},"criteria":["Login and data sync work across two devices","Widget or unit tests cover core logic","Released to testers through a store channel","Privacy policy covers collected data"]},"11-3":{"en":"Platform depth","hi":"प्लेटफ़ॉर्म की गहराई","brief":{"en":"Implement an advanced feature (custom rendering, background work, accessibility overhaul or performance profiling) and document measured improvements.","hi":"एक उन्नत फ़ीचर लागू करें (कस्टम रेंडरिंग, बैकग्राउंड कार्य, एक्सेसिबिलिटी सुधार या परफ़ॉर्मेंस प्रोफ़ाइलिंग) और मापे गए सुधार दर्ज करें।"},"criteria":["Before/after measurements are recorded","Accessibility checks pass on screen readers","Code reviewed by a peer","Contribution or write-up shared publicly"]},"12-0":{"en":"Understand a transaction end to end","hi":"एक लेन-देन को शुरू से अंत तक समझें","brief":{"en":"Create a test wallet, make transactions on a testnet, read them on a block explorer, and write a plain-language explanation of what happened.","hi":"एक टेस्ट वॉलेट बनाएं, टेस्टनेट पर लेन-देन करें, ब्लॉक एक्सप्लोरर पर पढ़ें, और सरल भाषा में समझाएं क्या हुआ।"},"criteria":["Only testnet funds were used","Two transactions are explained with hashes","Explains gas, block and confirmation in your own words","Lists three common scams to avoid"]},"12-1":{"en":"Your first smart contract","hi":"आपका पहला स्मार्ट कॉन्ट्रैक्ट","brief":{"en":"Write, test and deploy a simple contract (e.g. a tip jar or voting) to a testnet with a minimal web front end.","hi":"एक सरल कॉन्ट्रैक्ट (जैसे टिप जार या वोटिंग) लिखें, टेस्ट करें और न्यूनतम वेब फ्रंट एंड के साथ टेस्टनेट पर डिप्लॉय करें।"},"criteria":["Contract has automated tests that pass","Deployed to a testnet with a verified source","Front end can read and write to the contract","Known limitations are documented"]},"12-2":{"en":"A dApp with security review","hi":"सुरक्षा समीक्षा वाला dApp","brief":{"en":"Build a multi-contract application, run a security checklist and static analysis, and fix the findings.","hi":"एक बहु-कॉन्ट्रैक्ट एप्लिकेशन बनाएं, सुरक्षा चेकलिस्ट और स्थैतिक विश्लेषण चलाएं, और निष्कर्ष ठीक करें।"},"criteria":["Static analysis report is included","Reentrancy and access control are tested","Gas costs are measured and optimised once","Deployment scripts are reproducible"]},"12-3":{"en":"Protocol-level contribution","hi":"प्रोटोकॉल-स्तर योगदान","brief":{"en":"Solve advanced challenges (e.g. Ethernaut fully) and contribute a fix or feature to an open-source Web3 project.","hi":"उन्नत चुनौतियां हल करें (जैसे पूरा Ethernaut) और एक ओपन-सोर्स Web3 प्रोजेक्ट में सुधार या फ़ीचर का योगदान दें।"},"criteria":["Challenge completion is verifiable","Pull request is merged or substantively reviewed","Write-up explains one vulnerability class deeply","Mentor review attached"]},"13-0":{"en":"Compute and plot something real","hi":"कुछ असली गणना और प्लॉट करें","brief":{"en":"Using R, Julia or Scilab, load a dataset, compute summary statistics, and produce three labelled plots in a script that reruns cleanly.","hi":"R, Julia या Scilab से एक डेटासेट लोड करें, सारांश आंकड़े निकालें, और एक स्क्रिप्ट में तीन लेबल वाले प्लॉट बनाएं जो साफ़ दोबारा चले।"},"criteria":["Script runs from a fresh session without errors","Plots have titles, axes and units","Summary statistics are correct","Data source is cited"]},"13-1":{"en":"A reproducible analysis report","hi":"एक पुनरुत्पादन योग्य विश्लेषण रिपोर्ट","brief":{"en":"Write a literate report (R Markdown, Quarto or Pluto) that answers a question with data, code and figures in one document.","hi":"एक लिटरेट रिपोर्ट (R Markdown, Quarto या Pluto) लिखें जो डेटा, कोड और चित्रों के साथ एक दस्तावेज़ में सवाल का जवाब दे।"},"criteria":["Report renders from source in one step","Uses functions, not copy-pasted code","Includes at least one statistical model","Shared with a mentor for review"]},"13-2":{"en":"A numerical simulation","hi":"एक संख्यात्मक सिमुलेशन","brief":{"en":"Implement a simulation or numerical method (ODE solver, Monte Carlo, optimisation) and validate it against an analytical case.","hi":"एक सिमुलेशन या संख्यात्मक विधि (ODE सॉल्वर, मोंटे कार्लो, ऑप्टिमाइज़ेशन) लागू करें और उसे विश्लेषणात्मक मामले से सत्यापित करें।"},"criteria":["Matches an analytical solution within stated tolerance","Convergence or error is plotted","Performance is measured","Code is packaged with tests"]},"13-3":{"en":"A package for others","hi":"दूसरों के लिए एक पैकेज","brief":{"en":"Publish a small, documented package in R or Julia with tests and CI, and get one outside user or reviewer.","hi":"R या Julia में टेस्ट और CI के साथ एक छोटा, दस्तावेज़ीकृत पैकेज प्रकाशित करें, और एक बाहरी उपयोगकर्ता या समीक्षक पाएं।"},"criteria":["Installs from a public repository","Documentation with examples","CI runs tests on each change","One outside issue or review addressed"]},"14-0":{"en":"Ready to apply","hi":"आवेदन के लिए तैयार","brief":{"en":"Write a one-page resume, a professional email, and record a two-minute self-introduction in Hindi or English.","hi":"एक पेज का रिज़्यूमे, एक पेशेवर ईमेल लिखें, और हिंदी या अंग्रेज़ी में दो मिनट का आत्म-परिचय रिकॉर्ड करें।"},"criteria":["Resume is one page, error-free, saved as PDF","Email has a clear subject, greeting and request","Self-introduction covers who you are, what you can do, what you want","A mentor reviewed and you applied the feedback"]},"14-1":{"en":"A public portfolio and a mock interview","hi":"सार्वजनिक पोर्टफ़ोलियो और मॉक इंटरव्यू","brief":{"en":"Publish a portfolio page or GitHub profile with three projects, and complete a recorded mock interview with feedback.","hi":"तीन प्रोजेक्ट के साथ पोर्टफ़ोलियो पेज या GitHub प्रोफ़ाइल प्रकाशित करें, और फ़ीडबैक के साथ रिकॉर्डेड मॉक इंटरव्यू पूरा करें।"},"criteria":["Portfolio is live and links to three working projects","Each project has a short description of your role","Mock interview covers one technical and one behavioural question","Feedback notes list two improvements made"]},"14-2":{"en":"Write and present technical work","hi":"तकनीकी काम लिखें और प्रस्तुत करें","brief":{"en":"Write a technical article or documentation page and present it to a group, or make a first open-source contribution with a clear pull request.","hi":"एक तकनीकी लेख या दस्तावेज़ पेज लिखकर समूह को प्रस्तुत करें, या स्पष्ट पुल रिक्वेस्ट के साथ पहला ओपन-सोर्स योगदान करें।"},"criteria":["Article or PR is public","Follows a style guide","Presentation or PR discussion received feedback","Revisions were made in response"]},"14-3":{"en":"Mentor someone through a path","hi":"किसी को रास्ते में मेंटर करें","brief":{"en":"Guide another learner through one full tier of this app, reviewing their checkpoints and writing them a reference summary.","hi":"किसी अन्य सीखने वाले को इस ऐप के एक पूरे स्तर से गुज़ारें, उनके चेकपॉइंट की समीक्षा करें और उनके लिए संदर्भ सारांश लिखें।"},"criteria":["The learner completed the tier capstone","You reviewed at least five checkpoints with written comments","A summary of their strengths and next steps exists","The learner confirms the mentoring was useful"]}};
